            "Eefd24671a2e3ab19:1392:2088"
          ],
          "condicoes": [
            "após parada de plataforma que extinga a chama do flare",
            "na definição de procedimentos de ignição e reignição"
          ],
          "limites": [
            "não apresenta duração nem taxa numérica de purga no material recuperado",
            "a análise de dispersão e condições atmosféricas é mencionada sem critérios quantitativos no trecho"
          ]
        }
      ]
